solution.Account.java:
class Account {
    private final String owner;
    protected long balance;

    Account(String owner, long balance) {
        this.owner = owner;
        this.balance = balance;
    }

    String getOwner() { return owner; }
    long getBalance() { return balance; }

    void deposit(long amount) {
        if (amount <= 0) throw new IllegalArgumentException("deposit must be positive");
        balance += amount;
    }

    long available() { return balance; }

    boolean withdraw(long amount) {
        if (amount <= 0 || amount > available()) return false;
        balance -= amount;
        return true;
    }

    void monthEnd() { }

    @Override
    public String toString() {
        long abs = Math.abs(balance);
        return String.format("%s %s: %s%d.%02d", getClass().getSimpleName(), owner, balance < 0 ? "-" : "", abs / 100, abs % 100);
    }
}

solution.SavingsAccount.java:
class SavingsAccount extends Account {
    private final double yearlyRate;

    SavingsAccount(String owner, long balance, double yearlyRate) {
        super(owner, balance);
        this.yearlyRate = yearlyRate;
    }

    @Override
    void monthEnd() {
        balance += Math.round(balance * yearlyRate / 12);
    }
}

solution.CheckingAccount.java:
class CheckingAccount extends Account {
    private static final long FEE = 25;
    private final long overdraftLimit;

    CheckingAccount(String owner, long balance, long overdraftLimit) {
        super(owner, balance);
        this.overdraftLimit = overdraftLimit;
    }

    @Override
    long available() { return balance + overdraftLimit; }

    @Override
    boolean withdraw(long amount) {
        if (!super.withdraw(amount)) return false;
        balance -= FEE;
        return true;
    }

    @Override
    void monthEnd() {
        if (balance < 0) balance -= Math.round(-balance * 0.02);
    }
}

unitTests:
test("a plain account", () -> {
    Account a = new Account("Ada", 10_000);
    a.deposit(550);
    checkEq(a.withdraw(20_000), false);
    checkEq(a.withdraw(550), true);
    checkEq(a.withdraw(0), false);
    checkEq(a.getBalance(), 10_000L);
    checkThrows(IllegalArgumentException.class, () -> a.deposit(-5));
    a.monthEnd();
    checkEq(a.toString(), "Account Ada: 100.00");
});

test("savings interest", () -> {
    Account s = new SavingsAccount("Bo", 120_000, 0.03);
    s.monthEnd();
    checkEq(s.getBalance(), 120_300L);
    s.monthEnd();
    checkEq(s.getBalance(), 120_601L);
    checkEq(s.withdraw(200_000), false);
    checkEq(s.toString(), "SavingsAccount Bo: 1206.01");
});

test("checking with overdraft and fees", () -> {
    Account c = new CheckingAccount("Cy", 1_000, 5_000);
    checkEq(c.available(), 6_000L);
    checkEq(c.withdraw(6_000), true);
    checkEq(c.getBalance(), -5_025L);
    checkEq(c.withdraw(1), false);
    c.monthEnd();
    checkEq(c.getBalance(), -5_126L);
    checkEq(c.toString(), "CheckingAccount Cy: -51.26");
});

test("polymorphism", () -> {
    Account[] accounts = {new Account("A", 100), new SavingsAccount("B", 1_200, 0.1), new CheckingAccount("C", -100, 500)};
    long total = 0;
    for (Account acc : accounts) {
        acc.monthEnd();
        total += acc.getBalance();
    }
    checkEq(total, 100L + 1_210 + -102);
    check(accounts[2] instanceof Account, "CheckingAccount should extend Account");
});

